'use strict';
const $=selector=>document.querySelector(selector);
let quantity=1,mobile=false,count=0,toastTimer;
function logEvent(message){count++;$('#event-count').textContent=count+' event'+(count===1?'':'s');const row=document.createElement('li');row.textContent=new Date().toLocaleTimeString()+' · '+message;$('#events').prepend(row);while($('#events').children.length>15)$('#events').lastChild.remove();}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4000);}
$('#apply-promo-btn').onclick=()=>{const code=$('#promo-code').value.trim()||'WISPR50';$('#promo-code').value=code;$('#promo-error').textContent='Couldn’t apply code. Please try again. (Demo API failure)';$('#promo-error').hidden=false;const message='[Demo API simulation] FetchError: 500 Internal Server Error at POST /api/v1/cart/promo (PromoDatabasePoolTimeout: Connection terminated unexpectedly after 5000ms). Code: '+code;console.error(message);logEvent(message);};
function updateQuantity(){ $('#quantity').value=quantity;$('#subtotal').textContent='$'+(249*quantity).toFixed(2);$('#cart-total').textContent=quantity>=2?'$NaN':'$249.00';if(quantity>=2){try{const discount=undefined;const total=249*quantity*discount.discountMultiplier;$('#cart-total').textContent='$'+total;}catch(error){console.error(error.name+': '+error.message+' at calculateCartTotal (app.js)');logEvent(error.name+': '+error.message+' at calculateCartTotal');}}}
$('#increase-quantity').onclick=()=>{quantity++;updateQuantity();};$('#decrease-quantity').onclick=()=>{quantity=Math.max(1,quantity-1);updateQuantity();};
$('#shipping-address').onfocus=()=>{const input=$('#shipping-address');input.style.color='#ffffff';input.style.backgroundColor='#ffffff';const message='[A11y Audit] WCAG AA Contrast Failure (Ratio 1.0:1) on input#shipping-address: foreground #FFFFFF on background #FFFFFF';console.error(message);logEvent(message);};
$('#mobile-toggle').onclick=()=>{mobile=!mobile;$('#checkout-card').classList.toggle('mobile',mobile);$('#mobile-toggle').setAttribute('aria-pressed',String(mobile));$('#mobile-toggle').textContent=mobile?'Restore desktop ↗':'Simulate mobile ↗';if(mobile){const row=$('#checkout-cta-row');const width=$('#checkout-card').clientWidth;const message='[LayoutShift] Horizontal overflow detected on div.checkout-cta-row: scrollWidth ('+row.scrollWidth+'px) > clientWidth ('+width+'px) in a simulated 375px checkout card. Browser viewport '+innerWidth+'x'+innerHeight;console.error(message);logEvent(message);}};
$('#purchase-button').onclick=()=>toast('This is a fictional store. No payment was collected.');
$('#reset-demo').onclick=()=>{quantity=1;mobile=false;count=0;$('#checkout-card').classList.remove('mobile');$('#mobile-toggle').setAttribute('aria-pressed','false');$('#mobile-toggle').textContent='Simulate mobile ↗';$('#shipping-address').value='';$('#shipping-address').removeAttribute('style');$('#promo-code').value='';$('#promo-error').hidden=true;$('#events').replaceChildren();$('#event-count').textContent='0 events';updateQuantity();toast('Checkout reset. VoiceTrace capture remains active.');};
